   except sqlite3.IntegrityError:return self.sendj(409,{})
  m=re.match(r'/api/workspaces/([^/]+)/channels$',p)
  if m:
   w=q('SELECT * FROM workspaces WHERE slug=?',(m.group(1),),True)
   if not w:return self.sendj(404,{})
