   if d.get('is_private') and role[0] not in ('owner','admin'):return self.sendj(403,{})
   try: commit('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w[0],d.get('name'),int(bool(d.get('is_private'))),d.get('topic','')));return self.sendj(201,{'channel':channel_obj(q('SELECT * FROM channels WHERE id=last_insert_rowid()',(),True))})
   except sqlite3.IntegrityError:return self.sendj(409,{})
  m=re.match(r'/api/channels/(\d+)/join$',p)
  if m:
   c=q('SELECT * FROM channels WHERE id=?',(m.group(1),),True)
   if not c:return self.sendj(404,{})
   commit('INSERT OR IGNORE INTO chanmembers VALUES(?,?)',(c[0],u[0]));commit('INSERT OR IGNORE INTO members VALUES(?,?,?)',(c[1],u[0],'member'));return self.sendj(200,{'channel':channel_obj(c)})
  m=re.match(r'/api/channels/(\d+)/messages$',p)
  if m:return self.message(int(m.group(1)),u,d)
  m=re.match(r'/api/messages/(\d+)/reactions$',p)
  if m:
   mid=int(m.group(1)); x=q('SELECT channel_id FROM messages WHERE id=?',(mid,),True)
   if not x:return self.sendj(404,{})
   commit('INSERT OR IGNORE INTO reactions VALUES(?,?,?)',(mid,u[0],d.get('emoji','')));return self.sendj(200,{'reactions':msgobj(q('SELECT * FROM messages WHERE id=?',(mid,),True))['reactions']})
  if p=='/api/dms':
   other=int(d.get('user_id')); a=min(u[0],other);b=max(u[0],other); key=f'dm-{a}-{b}'; c=q('SELECT * FROM channels WHERE name=?',(key,),True)
   if not c: commit('INSERT INTO channels(workspace_id,name,is_dm) VALUES(?,?,1)',(0,key)); c=q('SELECT * FROM channels WHERE id=last_insert_rowid()',(),True)
   return self.sendj(200,{'channel_id':c[0]})
  if p.endswith('/read'):return self.sendj(200,{'read_state':self.readstate(u[0],int(p.split('/')[3]))})
