        if not triple and raw[i]=='\\' and i+1<len(raw):
            out.append(raw[i:i+2]); i+=2; continue
        if not triple and raw[i]==quote:
            out.append(raw[i]); i+=1; quote=None; continue
        if triple and raw.startswith('\\n',i):
            out.append('\n'); i+=2; continue
